INSERT INTO shoes (id, brand, model, purpose, stability, midsole, weight, drop_mm, stack_height, width, wide_available, carbon, price, image, images, summary, description, rating, review_count, like_count, liked) VALUES
  (1, '아식스', '젤 카야노 32', '조깅·회복주', '안정화', 'FF Blast Plus', 300, 8, 40, '보통', TRUE, FALSE, 199000, '/images/gel-kayano-32.png', '["/images/gel-kayano-32.png","/images/gel-kayano-32-1.png","/images/gel-kayano-32-2.png","/images/gel-kayano-32-3.png"]', '발이 안쪽으로 무너지는 분에게', '발이 안쪽으로 무너지는 것을 잡아주는 아식스의 대표 안정화입니다. 과내전이 있는 러너를 위해 만들어진 신발이라 발목이 흔들리는 느낌이 적습니다. 대신 그만큼 구조가 들어가 있어 무게는 무거운 편입니다. 4E 와이드 모델이 따로 나와 발볼이 넓어도 선택지가 있습니다.', 4.6, 5, 42, FALSE),
  (2, '나이키', '페가수스 42', '조깅·회복주', '중립화', '리액트X', 300, 10, 36, '보통', TRUE, FALSE, 169000, '/images/pegasus-42.png', '["/images/pegasus-42.png","/images/pegasus-42-1.png","/images/pegasus-42-2.png"]', '첫 러닝화를 고르는 분에게', '1982년부터 이어져 온 나이키의 가장 오래된 러닝화 계보입니다. 특출난 강점이 있다기보다 무난하게 다 되는 쪽이라 첫 러닝화로 자주 추천됩니다. 드롭이 10mm로 높은 편이라 뒤꿈치부터 착지하는 분에게 편안합니다. 42에서 앞발과 토박스 공간이 넓어졌고, 와이드 모델도 국내 정식 출시되어 발볼이 넓은 분에게도 선택지가 생겼습니다.', 4.4, 5, 69, TRUE),
  (3, '호카', '클리프톤 10', '조깅·회복주', '중립화', 'CMEVA', 278, 8, NULL, '넓음', TRUE, FALSE, 189000, '/images/clifton-10.png', '["/images/clifton-10.png","/images/clifton-10-1.png","/images/clifton-10-2.png"]', '푹신한 착지를 원하는 분에게', '호카 특유의 두툼한 미드솔로 푹신함을 앞세운 모델입니다. 착지 충격이 부담스러운 분이나 회복주를 자주 뛰는 분에게 잘 맞습니다. 와이드핏이 따로 나와 발볼이 넓어도 무리가 없습니다.', 4.6, 5, 55, FALSE),
  (4, '호카', '본디 9', 'LSD·장거리', '중립화', NULL, 297, 5, 43, '넓음', TRUE, FALSE, 229000, '/images/bondi-9.png', '["/images/bondi-9.png","/images/bondi-9-1.png","/images/bondi-9-2.png"]', '긴 거리를 자주 뛰는 분에게', '호카 라인업에서도 쿠션이 가장 두꺼운 축에 드는 모델입니다. 긴 거리를 뛸 때 발바닥에 쌓이는 피로를 줄이는 데 초점이 맞춰져 있습니다. 드롭이 5mm로 낮은 편이라 종아리에 부담이 올 수 있어, 처음 신는다면 짧은 거리부터 적응하시는 편이 좋습니다.', 4.4, 5, 29, FALSE),
  (5, '아식스', '노바블라스트 5', '템포·인터벌', '중립화', 'FF Blast Max', 255, 8, 41.5, '보통', TRUE, FALSE, 159000, '/images/novablast-5.png', '["/images/novablast-5.png","/images/novablast-5-1.png","/images/novablast-5-2.png","/images/novablast-5-3.png"]', '페이스를 올려보려는 분에게', '카본 플레이트 없이도 통통 튀는 느낌을 주는 아식스의 인기 모델입니다. 조깅에도 쓸 수 있지만 페이스를 올렸을 때 진가가 나오는 편이라, 템포런을 처음 해보시는 분께 자주 추천됩니다.', 4.6, 5, 60, FALSE),
  (6, '나이키', '알파플라이 3', '레이스', '중립화', 'ZoomX', 218, 8, NULL, '보통', FALSE, TRUE, 339000, '/images/alphafly-3.png', '["/images/alphafly-3.png","/images/alphafly-3-1.png","/images/alphafly-3-2.png","/images/alphafly-3-3.png","/images/alphafly-3-4.png","/images/alphafly-3-5.png"]', '대회에서 기록을 노리는 분에게', '에어 줌 유닛과 줌X 폼, 카본 플레이트를 결합한 나이키의 최상위 레이싱화입니다. 대회에서 기록을 노릴 때 쓰는 신발이라 일상 훈련용으로는 권장되지 않습니다. 근력이 충분히 갖춰지지 않은 상태에서 신으면 종아리와 아킬레스에 부담이 몰릴 수 있습니다.', 4.6, 5, 91, TRUE),
  (7, '브룩스', '고스트 17', '조깅·회복주', '중립화', 'DNA Loft v3', 289, 10, 37, '넓음', TRUE, FALSE, 189000, '/images/ghost-17.png', '["/images/ghost-17.png","/images/ghost-17-1.png"]', '발볼이 넓어 신발이 조이는 분에게', '브룩스의 대표 데일리 트레이너입니다. 폭 옵션이 네 가지나 되어 발볼이 넓은 분도 맞는 사이즈를 찾기 쉽습니다. DNA Loft v3 미드솔은 부드럽지만 물렁하지 않고, 드롭 10mm로 뒤꿈치부터 착지하는 분에게 편안합니다. 특별히 튀는 성격은 없지만 그래서 매일 신기 좋습니다.', 4, 6, 20, FALSE),
  (8, '뉴발란스', '프레시폼 X 880 v15', '조깅·회복주', '중립화', 'Fresh Foam X', 300, 6, 40.5, '보통', TRUE, FALSE, 179000, '/images/880-v15.png', '["/images/880-v15.png","/images/880-v15-1.png","/images/880-v15-2.png"]', '쿠션은 두껍되 드롭은 낮길 원하는 분에게', '뉴발란스의 오래된 데일리 트레이너로, 15세대에서 스택하이트가 40.5mm까지 올라갔습니다. 쿠션은 두툼하지만 드롭이 6mm로 낮은 편이라 종아리와 아킬레스건을 조금 더 쓰게 됩니다. 드롭이 높은 신발에서 넘어온다면 적응 기간을 두는 편이 좋습니다.', 4.4, 5, 40, FALSE),
  (9, '아디다스', '울트라부스트 5', '조깅·회복주', '중립화', 'Light Boost', 292, 10, 39, '보통', FALSE, FALSE, 239000, '/images/ultraboost-5.png', '["/images/ultraboost-5.png","/images/ultraboost-5-1.png","/images/ultraboost-5-2.png","/images/ultraboost-5-3.png","/images/ultraboost-5-4.png"]', '일상에서도 함께 신고 싶은 분에게', '러닝화와 일상화의 경계에 있는 모델입니다. 새로운 Light Boost 폼으로 이전 세대보다 가벼워졌고, 니트 어퍼는 발을 감싸듯 맞습니다. 다만 러닝 전용 모델에 비하면 무거운 편이라 기록을 노리는 훈련보다는 편안한 조깅과 일상 착용에 어울립니다.', 3.7, 6, 34, FALSE),
  (10, '사우코니', '엔돌핀 스피드 4', '템포·인터벌', '중립화', 'PWRRUN PB', 233, 8, 36, '보통', FALSE, FALSE, 229000, '/images/endorphin-speed-4.png', '["/images/endorphin-speed-4.png","/images/endorphin-speed-4-1.png","/images/endorphin-speed-4-2.png","/images/endorphin-speed-4-3.png","/images/endorphin-speed-4-4.png","/images/endorphin-speed-4-5.png"]', '카본화 전에 빠른 신발을 경험하고 싶은 분에게', '카본 플레이트 대신 나일론 플레이트를 넣은 이른바 슈퍼 트레이너입니다. 카본만큼 딱딱하지 않아 부담이 적으면서도 PWRRUN PB 폼의 반발력은 충분히 살아 있습니다. 233g으로 가벼워 템포런과 인터벌에 두루 쓰이고, 레이스에 나가기 전 단계로 자주 추천됩니다.', 4.4, 7, 71, FALSE),
  (11, '온', '클라우드몬스터 2', '템포·인터벌', '중립화', 'Helion', 295, 6, 35, '넓음', FALSE, FALSE, 259000, '/images/cloudmonster-2.png', '["/images/cloudmonster-2.png","/images/cloudmonster-2-1.png","/images/cloudmonster-2-2.png","/images/cloudmonster-2-3.png","/images/cloudmonster-2-4.png","/images/cloudmonster-2-5.png"]', '물렁한 쿠션보다 탄탄한 반발을 원하는 분에게', '온 특유의 클라우드 구조를 가장 크게 키운 모델입니다. 쿠션이 두툼하지만 푹신하기보다 단단하고 튕겨내는 느낌이라, 물렁한 신발이 답답했던 분에게 맞습니다. 295g으로 가벼운 편은 아니어서 인터벌보다는 꾸준한 템포 주행에 어울립니다.', 4, 5, 40, FALSE),
  (12, '아디다스', '아디제로 보스턴 13', '템포·인터벌', '중립화', 'Lightstrike Pro', 255, 7, 37, '보통', FALSE, FALSE, 209000, '/images/adizero-boston-13.png', '["/images/adizero-boston-13.png","/images/adizero-boston-13-1.png","/images/adizero-boston-13-2.png","/images/adizero-boston-13-3.png","/images/adizero-boston-13-4.png","/images/adizero-boston-13-5.png"]', '훈련과 레이스를 한 켤레로 해결하고 싶은 분에게', '카본 플레이트 대신 유리섬유 에너지 로드를 넣은 퍼포먼스 트레이너입니다. 로드가 발가락뼈처럼 나뉘어 있어 통짜 플레이트보다 발 움직임을 덜 방해합니다. 아디오스 프로만큼 극단적이지 않아 평소 훈련부터 하프마라톤까지 두루 쓸 수 있습니다.', 4.8, 5, 92, FALSE),
  (13, '아식스', '젤 님버스 27', 'LSD·장거리', '중립화', 'FF Blast Plus Eco', 305, 8, 43.5, '보통', TRUE, FALSE, 219000, '/images/gel-nimbus-27.png', '["/images/gel-nimbus-27.png","/images/gel-nimbus-27-1.png","/images/gel-nimbus-27-2.png","/images/gel-nimbus-27-3.png","/images/gel-nimbus-27-4.png","/images/gel-nimbus-27-5.png"]', '긴 거리에서 다리를 최대한 아끼고 싶은 분에게', '아식스 쿠션화 계열의 최상위 모델로, 스택하이트가 43.5mm까지 올라갑니다. 뒤꿈치에 퓨어젤이 들어가 착지 충격을 크게 줄여 주고, 폼이 무르지 않아 높은 쿠션에도 흔들림이 적습니다. 305g으로 무거운 편이라 속도보다 장거리 보호가 목적일 때 맞습니다.', 4.4, 5, 55, FALSE),
  (14, '아디다스', '슈퍼노바 라이즈 3', 'LSD·장거리', '중립화', 'Dreamstrike+', 264, 8, 36, '보통', FALSE, FALSE, 159000, '/images/supernova-rise-3.png', '["/images/supernova-rise-3.png","/images/supernova-rise-3-1.png","/images/supernova-rise-3-2.png","/images/supernova-rise-3-3.png"]', '부담 없는 가격으로 매일 신을 신발을 찾는 분에게', '최근 러닝화 가격이 계속 오르는 가운데 상대적으로 접근하기 쉬운 모델입니다. Dreamstrike+ 폼은 부드럽되 통통 튀는 성격이 있고, 264g으로 가벼워 긴 거리에서도 발이 덜 무겁습니다. 스택하이트가 36mm로 아주 높지는 않아 지면 감각이 어느 정도 남아 있습니다.', 4.2, 5, 49, FALSE),
  (15, '미즈노', '웨이브 라이더 29', 'LSD·장거리', '중립화', 'ENERZY NXT', 258, 10, 38, '보통', TRUE, FALSE, 169000, '/images/wave-rider-29.png', '["/images/wave-rider-29.png","/images/wave-rider-29-1.png","/images/wave-rider-29-2.png"]', '29년째 이어진 검증된 신발을 원하는 분에게', '29세대까지 이어진 미즈노의 대표 러닝화입니다. 오래 유지하던 12mm 드롭을 10mm로 낮추고 폼을 ENERZY NXT로 바꾸면서 한결 부드러워졌습니다. 튀는 구석 없이 안정적이라 장거리를 꾸준히 달리는 분에게 잘 맞습니다. 다만 미즈노는 전반적으로 발볼이 좁게 나오는 편입니다.', 4.4, 5, 38, FALSE),
  (16, '나이키', '베이퍼플라이 4', '레이스', '중립화', 'ZoomX', 167, 6, 35, '좁음', FALSE, TRUE, 309000, '/images/vaporfly-4.png', '["/images/vaporfly-4.png","/images/vaporfly-4-1.png","/images/vaporfly-4-2.png","/images/vaporfly-4-3.png","/images/vaporfly-4-4.png","/images/vaporfly-4-5.png","/images/vaporfly-4-6.png","/images/vaporfly-4-7.png"]', '10K에서 하프까지 기록을 노리는 분에게', '카본화 시대를 연 모델의 네 번째 세대입니다. 167g으로 역대 가장 가볍고, 이전 세대보다 스택하이트를 오히려 낮춰 지면에 더 가깝게 붙는 감각을 택했습니다. 알파플라이보다 가볍고 다루기 쉬워 첫 카본화로도 자주 언급되지만, 발볼이 좁으니 착화를 확인하는 편이 좋습니다.', 4.8, 6, 101, TRUE),
  (17, '아디다스', '아디제로 아디오스 프로 4', '레이스', '중립화', 'Lightstrike Pro', 201, 6, 39, '좁음', FALSE, TRUE, 329000, '/images/adios-pro-4.png', '["/images/adios-pro-4.png","/images/adios-pro-4-1.png","/images/adios-pro-4-2.png","/images/adios-pro-4-3.png","/images/adios-pro-4-4.png","/images/adios-pro-4-5.png","/images/adios-pro-4-6.png","/images/adios-pro-4-7.png"]', '풀코스에서 기록을 노리는 분에게', '통짜 카본 플레이트 대신 발가락뼈를 본뜬 다섯 개의 카본 로드를 넣었습니다. 밟는 부위에 따라 필요한 로드만 반응해 플레이트 특유의 뻣뻣함이 덜합니다. 201g으로 가볍고 컨티넨탈 고무 아웃솔이라 젖은 노면에서도 접지가 좋아 마라톤 레이스에서 자주 보입니다.', 4.6, 5, 78, FALSE),
  (18, '살로몬', '스피드크로스 6', '트레일', '중립화', 'EnergyCell+', 298, 10, 32, '보통', TRUE, FALSE, 189000, '/images/speedcross-6.png', '["/images/speedcross-6.png","/images/speedcross-6-1.png","/images/speedcross-6-2.png"]', '진흙과 미끄러운 산길을 자주 만나는 분에게', '2006년부터 이어진 살로몬의 대표 트레일화로, 접지력에 특화된 모델입니다. 5mm 깊이의 럭이 진흙을 파고들고 잘 털어내며, 한 번에 조이는 퀵레이스로 발을 단단히 잡아 줍니다. 어퍼가 촘촘해 이물질은 막아 주지만 여름에는 다소 덥게 느껴질 수 있습니다.', 4, 5, 68, FALSE),
  (19, '호카', '스피드고트 6', '트레일', '중립화', 'CMEVA', 283, 5, 40, '보통', TRUE, FALSE, 219000, '/images/speedgoat-6.png', '["/images/speedgoat-6.png","/images/speedgoat-6-1.png","/images/speedgoat-6-2.png","/images/speedgoat-6-3.png","/images/speedgoat-6-4.png","/images/speedgoat-6-5.png","/images/speedgoat-6-6.png"]', '산에서 아주 긴 거리를 달리는 분에게', '울트라 트레일 러너들에게 오래 사랑받아 온 모델입니다. 스택하이트 40mm로 트레일화 중에서도 쿠션이 두툼해 장시간 달려도 발바닥 피로가 덜합니다. 비브람 메가그립 아웃솔은 젖은 바위에서도 잘 붙고, 드롭이 5mm로 낮아 자연스러운 착지를 돕습니다.', 4.6, 5, 88, FALSE),
  (20, '아식스', '젤 트라부코 13', '트레일', '중립화', 'FF Blast Plus Eco', 288, 8, 34.5, '보통', FALSE, FALSE, 179000, '/images/gel-trabuco-13.png', '["/images/gel-trabuco-13.png","/images/gel-trabuco-13-1.png","/images/gel-trabuco-13-2.png","/images/gel-trabuco-13-3.png","/images/gel-trabuco-13-4.png","/images/gel-trabuco-13-5.png"]', '트레일을 처음 시작하는 분에게', '아식스의 만능형 트레일화로, 로드에서 트레일로 넘어오는 첫 신발로 자주 추천됩니다. 발바닥에 록플레이트가 들어가 돌밭에서 발을 보호하고, 뒤꿈치를 감싸는 구조가 단단해 울퉁불퉁한 길에서도 흔들림이 적습니다. 포장도로 구간이 섞인 코스에서도 무리 없이 달릴 수 있습니다.', 4.4, 5, 41, FALSE);
INSERT INTO reviews (id, shoe_id, author, rating, content, created_at, like_count, liked) VALUES
  (1, 1, '달리는곰', 5, '평발이라 안정화 찾다가 샀는데 5km 뛰어도 발목이 안 꺾이는 느낌입니다. 대신 확실히 무겁긴 하네요!!', '2026-07-18 00:00:00.000', 2, FALSE),
  (2, 1, '주말러너', 4, '기본 사이즈는 발볼이 좀 조여서 4E로 교환했습니다. 그 뒤로는 만족하고 있어요.', '2026-07-19 00:00:00.000', 0, FALSE),
  (3, 2, '퇴근런', 4, '무난합니다. 특별히 좋은 것도 나쁜 것도 없는데 그게 장점인 것 같아요. 첫 신발로 추천합니다.', '2026-07-17 00:00:00.000', 7, FALSE),
  (4, 2, '10K도전중', 5, '뒤꿈치 착지 습관이 있는데 편했습니다. 다만 무게가 300g 가까워서 후반에 좀 무겁게 느껴집니다!', '2026-07-20 00:00:00.000', 4, FALSE),
  (5, 3, '한강새벽', 5, '구름 위를 뛰는 느낌이라는 말이 과장이 아니네요. 회복주용으로 계속 신고 있습니다.', '2026-07-15 00:00:00.000', 6, FALSE),
  (6, 3, '느리게멀리', 5, '무릎이 안 좋아서 쿠션 위주로 찾았는데 만족합니다. 와이드로 샀더니 발볼도 편해요.', '2026-07-16 00:00:00.000', 2, FALSE),
  (7, 3, '초보탈출', 4, '푹신한 건 좋은데 페이스를 올리면 살짝 무르다는 느낌이 있습니다. 조깅 전용으로 쓰고 있어요.', '2026-07-20 00:00:00.000', 0, FALSE),
  (8, 4, '장거리연습', 4, '15km 넘어가도 발바닥이 덜 아픕니다. 드롭이 낮아서 처음엔 종아리가 좀 당겼어요.', '2026-07-14 00:00:00.000', 1, FALSE),
  (9, 5, '템포입문', 5, '확실히 통통 튑니다. 카본 없이 이 정도면 충분한 것 같아요.', '2026-07-13 00:00:00.000', 0, FALSE),
  (10, 5, '야간러닝', 4, '인터벌 할 때 좋습니다. 다만 천천히 뛸 땐 오히려 불편한 느낌이 있어요.', '2026-07-19 00:00:00.000', 3, FALSE),
  (11, 6, '서브포', 5, '대회용으로만 신고 있습니다. 확실히 다르긴 한데 훈련에 신었다가 종아리가 뭉쳤어요. 용도대로 쓰는 게 맞습니다.', '2026-07-12 00:00:00.000', 0, FALSE),
  (12, 1, '무릎지킴이', 5, '과내전이 심해서 안정화만 신는데 32는 그중에서도 편합니다. 예전 카야노보다 덜 딱딱해졌어요.', '2026-06-14 00:00:00.000', 4, FALSE),
  (13, 1, '주말10K', 4, '안정성은 확실한데 300g이 확실히 무겁긴 합니다. 회복주용으로만 쓰는 중입니다.', '2026-07-02 00:00:00.000', 2, FALSE),
  (14, 2, '런린이탈출', 4, '첫 러닝화로 샀는데 무난합니다. 다만 앞이 조금 좁게 느껴져서 와이드로 다시 살까 고민 중이에요.', '2026-06-21 00:00:00.000', 1, TRUE),
  (15, 2, '새벽6시', 5, '3년째 페가수스만 신고 있습니다. 매년 크게 안 바뀌는 게 오히려 장점 같아요.', '2026-07-09 00:00:00.000', 1, TRUE),
  (16, 3, '발바닥통증', 5, '족저근막염 때문에 쿠션 찾다가 골랐는데 확실히 편합니다. 무게도 278g으로 가벼운 편이라 좋아요.', '2026-06-18 00:00:00.000', 0, FALSE),
  (17, 3, '호카입문', 4, '푹신하긴 한데 생각보다 지면 감각이 없어서 처음엔 어색했습니다. 지금은 적응했어요.', '2026-07-05 00:00:00.000', 3, FALSE),
  (18, 4, '30K주자', 5, '장거리 끝나고 다리가 확실히 덜 아픕니다. 무겁지만 그만한 값을 합니다.', '2026-06-25 00:00:00.000', 5, FALSE),
  (19, 4, '발볼왕', 4, '발볼 넓은 사람에게 정말 편합니다. 다만 드롭 5mm라 종아리가 처음엔 좀 당겼어요.', '2026-07-08 00:00:00.000', 4, FALSE),
  (20, 4, '퇴근런', 5, '출퇴근 겸용으로도 신는데 하루 종일 서 있어도 발이 편합니다.', '2026-07-16 00:00:00.000', 4, FALSE),
  (21, 5, '인터벌지옥', 5, '255g에 이 쿠션이면 반칙 아닌가요. 템포런에서 확실히 잘 튕겨줍니다.', '2026-06-29 00:00:00.000', 3, FALSE),
  (22, 5, '트랙러너', 5, '스택 41.5mm인데 불안하지 않은 게 신기합니다. 인터벌부터 조깅까지 다 되는 만능이에요.', '2026-07-13 00:00:00.000', 0, FALSE),
  (23, 6, '서브3도전', 5, '풀코스에서 신었는데 30K 이후가 확실히 다릅니다. 가격만 빼면 완벽해요.', '2026-06-30 00:00:00.000', 2, FALSE),
  (24, 6, '카본첫경험', 4, '반발력은 엄청난데 초보가 신기엔 확실히 부담됩니다. 종아리가 며칠 아팠어요.', '2026-07-14 00:00:00.000', 1, TRUE),
  (25, 7, '넓은발러너', 4, '폭 옵션이 많아서 4E로 샀는데 드디어 발이 안 조입니다. 이것만으로도 만족해요.', '2026-06-16 00:00:00.000', 2, FALSE),
  (26, 7, '출근전달리기', 5, '특별한 건 없는데 그게 장점입니다. 매일 신어도 질리지 않아요.', '2026-07-01 00:00:00.000', 4, FALSE),
  (27, 7, '속도욕심', 4, '편하긴 한데 페이스를 올리면 좀 둔합니다. 조깅 전용으로 쓰는 게 맞는 것 같아요.', '2026-07-17 00:00:00.000', 2, FALSE),
  (28, 8, '뉴발매니아', 4, '쿠션이 확 늘었는데 드롭이 6mm라 예전 880과는 느낌이 많이 다릅니다. 적응 기간이 필요했어요.', '2026-06-22 00:00:00.000', 0, FALSE),
  (29, 8, '회복주전용', 4, '300g이라 무겁긴 한데 쿠션은 확실합니다. 훈련 다음 날 회복주로 딱이에요.', '2026-07-11 00:00:00.000', 2, FALSE),
  (30, 9, '데일리슈즈', 3, '일상화로는 정말 좋은데 러닝화로 보면 무겁습니다. 5K 넘어가면 발이 무거워져요.', '2026-06-19 00:00:00.000', 3, FALSE),
  (31, 9, '디자인우선', 4, '솔직히 예뻐서 샀습니다. 가볍게 뛰는 정도면 충분히 괜찮아요.', '2026-07-03 00:00:00.000', 4, FALSE),
  (32, 9, '부스트팬', 4, '라이트부스트로 바뀌면서 확실히 가벼워졌습니다. 다만 가격이 좀 부담스럽네요.', '2026-07-19 00:00:00.000', 2, FALSE),
  (33, 10, '템포런중독', 5, '카본 없이 이 정도 반발이면 충분합니다. 나일론 플레이트라 발이 덜 피곤해요.', '2026-06-17 00:00:00.000', 4, FALSE),
  (34, 10, '하프준비중', 5, '233g이 정말 가볍게 느껴집니다. 훈련용과 레이스용을 한 켤레로 해결했어요.', '2026-07-04 00:00:00.000', 1, FALSE),
  (35, 10, '발볼걱정', 4, '성능은 최고인데 앞볼이 좁습니다. 반 사이즈 크게 사는 걸 추천해요.', '2026-07-12 00:00:00.000', 1, TRUE),
  (36, 10, '사우코니처음', 5, '카본화 사기 전에 이걸 먼저 신어보라는 말이 무슨 뜻인지 알겠습니다.', '2026-07-20 00:00:00.000', 1, FALSE),
  (37, 11, '온첫구매', 4, '쿠션이 푹신하지 않고 단단하게 튕깁니다. 물렁한 신발 싫어하는 분에게 맞아요.', '2026-06-23 00:00:00.000', 0, FALSE),
  (38, 11, '가성비고민', 3, '성능 대비 가격이 아쉽습니다. 295g으로 무겁기도 하고요.', '2026-07-06 00:00:00.000', 4, FALSE),
  (39, 11, '발볼넓음', 4, '온 치고는 앞이 넓게 나와서 좋았습니다. 다만 반 사이즈 줄여야 맞더라고요.', '2026-07-18 00:00:00.000', 2, FALSE),
  (40, 12, '10K레이스', 5, '에너지로드가 통짜 플레이트보다 자연스럽습니다. 발이 따로 노는 느낌이 없어요.', '2026-06-20 00:00:00.000', 3, FALSE),
  (41, 12, '훈련도레이스도', 4, '255g에 이 정도 반발이면 훌륭합니다. 다만 앞볼이 좁아 사이즈 확인은 필수예요.', '2026-07-07 00:00:00.000', 3, FALSE),
  (42, 12, '아디제로파', 5, '컨티넨탈 아웃솔이 정말 잘 붙습니다. 비 오는 날에도 미끄러진 적이 없어요.', '2026-07-15 00:00:00.000', 1, FALSE),
  (43, 13, '마라톤준비', 5, '43.5mm 스택인데 흔들리지 않는 게 인상적입니다. 장거리 훈련이 훨씬 편해졌어요.', '2026-06-15 00:00:00.000', 0, FALSE),
  (44, 13, '무게민감', 4, '쿠션은 최고지만 305g은 확실히 무겁습니다. 속도 훈련에는 안 맞아요.', '2026-06-28 00:00:00.000', 0, FALSE),
  (45, 13, '님버스26에서', 5, '26보다 2mm 두꺼워졌는데 무게는 그대로입니다. 발 뒤꿈치 충격이 확실히 줄었어요.', '2026-07-10 00:00:00.000', 3, FALSE),
  (46, 13, '체중많이나감', 4, '80kg 넘는데 이 정도 쿠션이면 안심됩니다. 다만 여름엔 좀 덥네요.', '2026-07-21 00:00:00.000', 4, FALSE),
  (47, 14, '가성비추구', 4, '이 가격에 이 성능이면 훌륭합니다. 요즘 러닝화 가격 생각하면 더 그래요.', '2026-06-24 00:00:00.000', 3, FALSE),
  (48, 14, '매일10K', 5, '264g으로 가벼워서 매일 신기 좋습니다. 폼도 통통 튀는 게 재밌어요.', '2026-07-02 00:00:00.000', 0, FALSE),
  (49, 14, '좁은신발싫어', 4, '성능은 만족하는데 앞볼이 살짝 좁습니다. 발 넓은 분은 신어보고 사세요.', '2026-07-16 00:00:00.000', 2, FALSE),
  (50, 15, '미즈노20년', 4, '드디어 드롭이 10mm로 내려왔네요. 12mm 시절보다 훨씬 자연스럽습니다.', '2026-06-26 00:00:00.000', 5, FALSE),
  (51, 15, '안정지향', 4, '튀는 구석 없이 안정적입니다. 재미는 없어도 믿고 신을 수 있어요.', '2026-07-08 00:00:00.000', 4, FALSE),
  (52, 15, '장거리위주', 5, '웨이브 플레이트 덕인지 긴 거리에서도 안 흔들립니다. 발볼만 조금 넓었으면 좋겠어요.', '2026-07-19 00:00:00.000', 1, FALSE),
  (53, 16, '하프서브90', 5, '167g이 진짜 아무것도 안 신은 것 같습니다. 하프에서 개인 기록 경신했어요.', '2026-06-27 00:00:00.000', 6, FALSE),
  (54, 16, '카본입문', 5, '알파플라이보다 다루기 쉽습니다. 첫 카본화로 이걸 고른 게 잘한 선택이었어요.', '2026-07-05 00:00:00.000', 2, FALSE),
  (55, 16, '발볼넓은편', 4, '성능은 의심의 여지가 없는데 발볼이 정말 좁습니다. 저는 반 사이즈 올렸어요.', '2026-07-13 00:00:00.000', 1, FALSE),
  (56, 16, '스택낮아짐', 5, '3세대보다 스택을 낮춘 게 오히려 좋습니다. 지면이 가까워서 안정감이 있어요.', '2026-07-22 00:00:00.000', 4, FALSE),
  (57, 17, '풀코스전용', 5, '마라톤에서 신으려고 아껴 신고 있습니다. 30K 이후에도 폼이 죽지 않아요.', '2026-06-21 00:00:00.000', 1, FALSE),
  (58, 17, '로드vs플레이트', 4, '카본 로드라 통짜 플레이트보다 부드럽습니다. 대신 그만큼 추진력은 덜한 느낌이에요.', '2026-07-06 00:00:00.000', 2, FALSE),
  (59, 17, '비오는날레이스', 5, '젖은 노면에서 접지력이 압도적입니다. 컨티넨탈 고무가 확실히 다르네요.', '2026-07-17 00:00:00.000', 1, FALSE),
  (60, 18, '진흙산길', 4, '진흙에서 이만한 게 없습니다. 럭이 깊어서 잘 파고들고 털어내기도 좋아요.', '2026-06-18 00:00:00.000', 3, FALSE),
  (61, 18, '트레일10년', 5, '5세대보다 가벼워지고 앞볼도 넓어졌습니다. 스피드크로스의 정체성은 그대로예요.', '2026-07-01 00:00:00.000', 0, FALSE),
  (62, 18, '여름트레일', 2, '그립은 최고인데 어퍼가 촘촘해서 여름엔 발이 정말 더워요!', '2026-07-14 00:00:00.000', 1, TRUE),
  (63, 19, '울트라준비', 5, '50K 뛰었는데 발바닥이 멀쩡합니다. 트레일화 중에 이만한 쿠션이 없어요.', '2026-06-16 00:00:00.000', 0, FALSE),
  (64, 19, '젖은바위', 5, '비브람 메가그립이 젖은 바위에서도 잘 붙습니다. 내리막에서 겁이 안 나요.', '2026-06-29 00:00:00.000', 1, FALSE),
  (65, 19, '스피드고트5에서', 4, '5세대보다 뻣뻣해진 느낌입니다. 쿠션은 늘었는데 지면 감각은 줄었어요.', '2026-07-11 00:00:00.000', 4, FALSE),
  (66, 19, '산악마라톤', 4, '무난하게 다 잘합니다. 대신 아주 기술적인 구간에선 조금 둔하게 느껴져요.', '2026-07-20 00:00:00.000', 0, FALSE),
  (67, 20, '로드에서트레일로', 4, '포장도로 구간이 섞인 코스에서도 무리 없습니다. 트레일 입문용으로 추천해요.', '2026-06-25 00:00:00.000', 0, FALSE),
  (68, 20, '돌밭주의', 5, '록플레이트 덕에 돌을 밟아도 발바닥이 아프지 않습니다. 이 가격에 이 정도면 훌륭해요.', '2026-07-09 00:00:00.000', 0, FALSE),
  (69, 16, '주갑열', 5, '일단 디자인이 너무 예뻐서 구매했어요...!!!', '2026-07-23 00:00:00.000', 3, FALSE),
  (70, 2, 'ㅁㅁㅁ', 4, '신발이 너무 좋아요!', '2026-07-23 07:04:54.447', 2, FALSE),
  (71, 12, '김진하', 5, '대회를 신청하고 이 신발을 구매했는데 마음에 들어요! ', '2026-07-24 03:39:31.840', 3, FALSE),
  (72, 1, '초보러너민지', 5, '발이 안쪽으로 무너지는 편인데 이 신발 신고 나서 무릎 아픈 게 확실히 줄었어요.', '2026-07-27 22:19:18.668', 3, FALSE),
  (73, 4, '장거리도전', 4, '40mm 스택하이트가 처음엔 어색했는데 20km 넘어가니 왜 두꺼운지 알겠더라고요.', '2026-07-27 15:19:18.668', 5, FALSE),
  (74, 5, '인터벌러너', 4, '빠른 페이스로 치고 나갈 때 반발력이 확실히 다릅니다. 조깅화보단 인터벌용.', '2026-07-27 08:19:18.668', 2, FALSE),
  (75, 6, '레이스데이', 5, '10K 개인 기록 3분 단축했어요. 카본 플레이트 반발력이 확실히 다릅니다.', '2026-07-27 01:19:18.668', 12, FALSE),
  (76, 6, '첫풀코스', 4, '가볍긴 한데 발볼이 좁아서 발가락 쪽이 좀 눌려요. 반 사이즈 크게 신으세요.', '2026-07-26 18:19:18.668', 6, FALSE),
  (77, 7, '매일러너', 5, '매일 신어도 부담 없는 조깅화. 무난하게 오래 신기 좋아요.', '2026-07-26 11:19:18.668', 4, FALSE),
  (78, 7, '발볼넓어요', 4, '브룩스가 발볼이 넉넉하다더니 정말 편해요. 국내 브랜드보다 낫네요.', '2026-07-26 04:19:18.668', 3, FALSE),
  (79, 8, '뉴발유저', 5, '쿠션이 정말 푹신해서 장거리 회복주에 딱입니다.', '2026-07-25 21:19:18.668', 3, FALSE),
  (80, 8, '첫러닝화', 4, '가격 대비 만족스러운데 무게가 좀 나가는 편이에요.', '2026-07-25 14:19:18.668', 2, FALSE),
  (81, 8, '회복주전용', 5, '빡센 훈련 다음날 회복주용으로 신는데 발이 편해요.', '2026-07-25 07:19:18.668', 4, FALSE),
  (82, 9, '아디다스팬', 4, '부스트 쿠션 특유의 탱글한 느낌이 좋아요. 일상화로도 손색없습니다.', '2026-07-25 00:19:18.668', 5, FALSE),
  (83, 9, '출퇴근러너', 4, '회사 다녀와서 가볍게 뛰기 좋은 신발. 디자인도 무난해요.', '2026-07-24 17:19:18.668', 2, FALSE),
  (84, 10, '템포훈련중', 5, '템포런 훈련용으로 구매했는데 딱 원하던 반응성이에요.', '2026-07-24 10:19:18.668', 4, FALSE),
  (85, 11, '온신발첫구매', 4, '클라우드테크 쿠션이 특이한데 적응되니 편합니다.', '2026-07-24 03:19:18.668', 3, FALSE),
  (86, 11, '디자인중시', 5, '성능도 좋지만 일단 예뻐서 삽니다. 인터벌에도 무난해요.', '2026-07-23 20:19:18.668', 6, FALSE),
  (87, 12, '보스턴시리즈', 5, '보스턴 시리즈 계속 신고 있는데 13세대가 제일 안정적이에요.', '2026-07-23 13:19:18.668', 3, FALSE),
  (88, 13, '장거리안정화', 4, '안정화인데도 무겁지 않아서 LSD 훈련에 자주 신어요.', '2026-07-23 06:19:18.668', 3, FALSE),
  (89, 14, '슈퍼노바입문', 4, '장거리용으로 처음 신어봤는데 쿠션감이 부드러워요.', '2026-07-22 23:19:18.668', 2, FALSE),
  (90, 14, '주말러너', 4, '주말 장거리 러닝용으로 만족스럽습니다.', '2026-07-22 16:19:18.668', 3, FALSE),
  (91, 15, '미즈노웨이브', 5, '웨이브 플레이트 특유의 안정감이 장거리에 딱이에요.', '2026-07-22 09:19:18.668', 4, FALSE),
  (92, 15, '오래된유저', 4, '라이더 시리즈만 몇 년째 신는데 29도 무난합니다.', '2026-07-22 02:19:18.668', 2, FALSE),
  (93, 16, '서브3도전', 5, '마라톤 서브3 페이스메이커로 신었는데 최고였습니다. 가볍고 반발력 최고.', '2026-07-21 19:19:18.668', 15, FALSE),
  (94, 17, '레이스전용화', 5, '레이스 당일에만 신는 전용화로 씁니다. 확실히 기록이 다르네요.', '2026-07-21 12:19:18.668', 5, FALSE),
  (95, 17, '아디제로팬', 4, '가볍고 반발력 좋은데 쿠션이 얇아서 장거리엔 안 맞아요.', '2026-07-21 05:19:18.668', 3, FALSE),
  (96, 18, '트레일입문', 4, '산길 그립력이 확실히 다릅니다. 젖은 바위에서도 안정적이에요.', '2026-07-20 22:19:18.668', 3, FALSE),
  (97, 18, '주말산길러너', 5, '발볼 좁은 편이라 두꺼운 양말 신으면 딱 맞아요.', '2026-07-20 15:19:18.668', 2, FALSE),
  (98, 19, '호카트레일', 5, '쿠션이 두꺼워서 긴 트레일 코스에도 발이 편해요.', '2026-07-20 08:19:18.668', 4, FALSE),
  (99, 20, '트라부코첫구매', 4, '아식스 트레일화 처음 신어보는데 접지력이 좋네요.', '2026-07-20 01:19:18.668', 2, FALSE),
  (100, 20, '주말등산러너', 5, '가벼운 산길 정도는 이걸로 충분합니다.', '2026-07-19 18:19:18.668', 3, FALSE),
  (101, 20, '트레일러닝시작', 4, '입문용으로 무난하고 가격도 합리적이에요.', '2026-07-19 11:19:18.668', 2, FALSE),
  (102, 9, '좁은발볼', 3, '발볼이 좁아서 불편해요. 반 사이즈 크게 신는 걸 추천합니다.', '2026-07-28 07:40:56.598', NULL, FALSE),
  (103, 7, '러너사랑', 2, '밑창이 얇아서 아스팔트 요철이 그대로 느껴져요. 쿠션은 좋은데 지면 충격은 좀 있는 편입니다.', '2026-07-28 08:35:36.920', NULL, FALSE),
  (104, 10, '실용주의자', 2, '페이스를 올리면 반응은 좋은데, 신다 보니 두 달 만에 뒤꿈치 안쪽이 닳아서 쿠션이 꺼졌어요. 내구성이 걱정됩니다.', '2026-07-28 08:39:28.906', 20, FALSE),
  (105, 10, '이상주의자', 5, '와 이거 진짜 최고예요! 몇 달째 매일 신고 있는데 쿠션 하나도 안 죽고 완전 튼튼해요. 내구성 걱정하시는 분들 있던데 전혀 걱정 안 하셔도 됩니다!', '2026-07-28 08:41:06.821', 20, FALSE);
INSERT INTO terms (id, term_key, name, short, description) VALUES
  (1, 'drop', '드롭', '뒤꿈치와 앞꿈치의 높이 차이', '뒤꿈치와 앞꿈치의 높이 차이(mm)입니다. 클수록 뒤꿈치 착지가 편하고 무릎 부담이 줄지만, 낮으면 종아리와 아킬레스건을 더 쓰게 되어 적응 기간이 필요합니다. 시중 제품은 대체로 6~12mm이며 초보라면 8~10mm가 무난합니다.'),
  (2, 'stackHeight', '스택하이트', '미드솔 두께 — 발밑 쿠션의 양', '미드솔의 두께(mm)로 발밑에 깔린 쿠션의 양을 뜻합니다. 30mm 이하면 얇은 편, 40mm 이상이면 두꺼운 편입니다. 두꺼울수록 푹신하고 장거리에 유리하지만 무게가 늘고 지면 감각이 둔해집니다.'),
  (3, 'pronation', '프로네이션', '착지할 때 발이 안쪽으로 기울어지는 움직임', '착지할 때 발이 안쪽으로 살짝 기울어지는 자연스러운 움직임으로, 충격을 흡수하는 정상적인 동작입니다. 이 움직임이 과도한 경우를 과내전(오버프로네이션)이라고 합니다. 신던 운동화 밑창의 안쪽만 유독 닳았다면 과내전일 가능성이 있습니다.'),
  (4, 'neutral', '중립화', '교정 장치 없이 쿠션을 균등하게 배치한 신발', '교정 장치 없이 쿠션을 균등하게 배치한 신발로, 시중 러닝화 대부분이 여기에 해당합니다. 흔히 말하는 ''쿠션화''와 같은 말이며, 쿠션이 더 많다는 뜻은 아닙니다.'),
  (5, 'stability', '안정화', '발이 안쪽으로 무너지는 것을 막아주는 신발', '미드솔 안쪽에 단단한 소재를 넣어 발이 안쪽으로 무너지는 것을 막아주는 신발입니다. 과내전이 있는 분에게 필요하며, 해당되지 않는 분이 신으면 오히려 불편할 수 있습니다. 더 좋은 신발이 아니라 발 유형에 맞춰 고르는 것입니다.'),
  (6, 'carbon', '카본 플레이트', '미드솔에 삽입된 탄성판 — 반발력을 크게 높임', '미드솔에 삽입된 탄소섬유 판으로 반발력을 크게 높여줍니다. 다만 가격이 비싸고, 근력과 러닝 기술이 충분하지 않은 상태에서 신으면 종아리와 발목, 아킬레스에 부담이 집중될 수 있습니다.'),
  (7, 'width', '발볼', '신발 앞쪽의 좌우 폭', '신발 앞쪽의 좌우 폭입니다. 한국인은 발볼이 넓은 편이라 서양 브랜드의 기본 사이즈가 조이는 경우가 있습니다. 이럴 때는 같은 모델의 와이드(2E, 4E) 버전을 확인해 보시는 것이 좋습니다.'),
  (8, 'midsole', '미드솔', '겉창과 안창 사이의 쿠션층', '겉창(아웃솔)과 안창 사이에 있는 쿠션층으로, 러닝화의 성격을 결정하는 핵심 부위입니다. 브랜드마다 폼 소재에 고유한 이름을 붙입니다. 줌X, FF Blast+, 리액트X 등이 그 예입니다.'),
  (9, 'trail', '트레일 러닝', '포장도로가 아닌 산길·흙길을 달리는 러닝', '포장도로가 아닌 산길과 흙길, 자갈길을 달리는 러닝입니다. 트레일화는 밑창 돌기가 깊고 어퍼가 튼튼하며 앞코에 토캡 보강이 들어가 무게가 무거운 편입니다.'),
  (10, 'tempo', '템포런', '평소보다 빠른 페이스로 일정하게 달리는 훈련', '평소 조깅보다 빠른 페이스를 일정하게 유지하며 달리는 훈련입니다. 숨이 약간 찰 정도의 강도로, 지구력을 끌어올리는 데 쓰입니다.'),
  (11, 'lsd', 'LSD', '느린 페이스로 길게 달리는 훈련', 'Long Slow Distance의 줄임말로, 느린 페이스를 유지하며 긴 거리를 달리는 훈련입니다. 심폐 지구력을 기르는 데 쓰이며 쿠션이 두꺼운 신발이 유리합니다.'),
  (12, 'weight', '무게', '신발 한 짝의 무게', '신발 한 짝의 무게입니다. 브랜드가 정한 대표 사이즈(보통 270~280mm) 기준으로 표기하기 때문에, 실제 신는 사이즈에 따라 달라집니다. 사이즈가 10mm 커질 때마다 5~10g 정도 늘어납니다. 220g 이하면 가벼운 편, 300g 이상이면 무거운 편입니다.'),
  (12, 'outsole', '아웃솔', '지면에 닿는 겉창', '지면에 직접 닿는 겉창입니다. 고무 소재로 접지력과 내구성을 담당하며, 마모가 잦은 부위에 고무를 더 두껍게 배치하기도 합니다. 트레일화는 흙길에서 미끄러지지 않도록 돌기가 깊게 파여 있습니다.');
